#!/bin/bash

set -ouex pipefail

# Copy the contents of system_files/ of the git repo to /
cp -avf "/ctx/system_files"/. /

### HoussamOS branding
# The art itself lives in system_files/ and is generated by branding/make_branding.py.

# Name, logo and links. ID/ID_LIKE stay Bazzite's so its update and setup tools keep working.
set_os_release() {
    if grep -q "^$1=" /usr/lib/os-release; then
        sed -i "s|^$1=.*|$1=\"$2\"|" /usr/lib/os-release
    else
        echo "$1=\"$2\"" >> /usr/lib/os-release
    fi
}
set_os_release NAME "HoussamOS"
set_os_release PRETTY_NAME "HoussamOS"
set_os_release DEFAULT_HOSTNAME "houssamos"
set_os_release LOGO "houssamos-logo"
set_os_release HOME_URL "https://github.com/Houssam-2021/housos"
set_os_release DOCUMENTATION_URL "https://github.com/Houssam-2021/housos#readme"
set_os_release SUPPORT_URL "https://github.com/Houssam-2021/housos/issues"
set_os_release BUG_REPORT_URL "https://github.com/Houssam-2021/housos/issues"

# Bazzite's own tools read the image name from here
if [ -f /usr/share/ublue-os/image-info.json ] && command -v jq > /dev/null; then
    jq --arg name "${IMAGE_NAME:-houssamos}" \
        '."image-name" = $name
        | ."image-vendor" = "houssam-2021"
        | ."image-ref" = "ostree-unverified-registry:ghcr.io/houssam-2021/\($name)"' \
        /usr/share/ublue-os/image-info.json > /tmp/image-info.json
    mv /tmp/image-info.json /usr/share/ublue-os/image-info.json
fi

# Logos: install the HoussamOS icon, then put it in place of every Bazzite/Fedora logo icon
icons=/usr/share/houssamos/icons
for size in 16 22 24 32 36 48 64 96 128 256 512; do
    install -Dm644 "$icons/$size.png" "/usr/share/icons/hicolor/${size}x${size}/apps/houssamos-logo.png"
done
install -Dm644 "$icons/houssamos-logo.svg" /usr/share/icons/hicolor/scalable/apps/houssamos-logo.svg
find /usr/share/icons /usr/share/pixmaps -type f \
    \( -name 'distributor-logo*' -o -name 'bazzite-logo*' -o -name 'fedora-logo-icon*' -o -name 'start-here*' \) \
    -print0 | while IFS= read -r -d '' f; do
    case "$f" in
        *.svg) cp "$icons/houssamos-logo.svg" "$f" ;;
        *.svgz) gzip -c "$icons/houssamos-logo.svg" > "$f" ;;
        *.png)
            size=$(grep -oE '/[0-9]+x[0-9]+/' <<< "$f" | grep -oE '[0-9]+' | head -n 1 || true)
            [ -n "$size" ] && [ -f "$icons/$size.png" ] || size=256
            cp "$icons/$size.png" "$f"
            ;;
    esac
done
if command -v gtk-update-icon-cache > /dev/null; then
    for theme in /usr/share/icons/*/; do
        [ -f "${theme}index.theme" ] && gtk-update-icon-cache -qf "$theme" || true
    done
fi

# Wallpaper: the desktop, lock screen and login screen all default to /usr/share/backgrounds/default.jxl
dnf5 install -y libjxl-utils
cjxl -q 95 /usr/share/wallpapers/HoussamOS/contents/images/*.png /usr/share/backgrounds/houssamos.jxl
dnf5 remove -y libjxl-utils
ln -sf houssamos.jxl /usr/share/backgrounds/default.jxl
ln -sf houssamos.jxl /usr/share/backgrounds/default-dark.jxl

# Glass dock and top bar: make the HoussamOS Glass Plasma theme the default. The layout itself
# is set per user by /usr/share/plasma/shells/org.kde.plasma.desktop/contents/updates/houssamos-layout.js
if command -v kwriteconfig6 > /dev/null; then
    kwriteconfig6 --file /etc/xdg/plasmarc --group Theme --key name houssamos-glass
else
    printf '\n[Theme]\nname=houssamos-glass\n' >> /etc/xdg/plasmarc
fi

# Boot animation (the initramfs that carries it is rebuilt at the end of this script)
dnf5 install -y plymouth-plugin-script
plymouth_conf=/etc/plymouth/plymouthd.conf
if [ -f "$plymouth_conf" ] && grep -q '^Theme=' "$plymouth_conf"; then
    sed -i 's/^Theme=.*/Theme=houssamos/' "$plymouth_conf"
elif [ -f "$plymouth_conf" ] && grep -q '^\[Daemon\]' "$plymouth_conf"; then
    sed -i '/^\[Daemon\]/a Theme=houssamos' "$plymouth_conf"
else
    mkdir -p /etc/plymouth
    printf '[Daemon]\nTheme=houssamos\n' >> "$plymouth_conf"
fi

### Install packages
# Packages can be installed from any enabled repo on the image (Fedora, RPM Fusion).
# dnf5 install -y <package>

### Repository cleanup
# bootc-image-builder reads /etc/yum.repos.d directly when it builds the installer ISO.
# It ignores dnf5's repos.override.d (where Bazzite turns repos off with
# "config-manager setopt") and fails on any enabled repo whose GPG key file is missing.

# Turn off one repo id in whichever .repo file defines it
disable_repo() {
    local id="$1" f
    for f in /etc/yum.repos.d/*.repo; do
        grep -qF "[${id}]" "$f" || continue
        sed -i -e "/^\[${id}\]/,/^\[/{/^enabled[[:space:]]*=/d}" -e "/^\[${id}\]/a enabled=0" "$f"
        echo "Disabled repo ${id} in ${f}"
    done
}

# Copy repos that dnf5 overrides turned off into the .repo files
if compgen -G "/etc/dnf/repos.override.d/*.repo" > /dev/null; then
    awk '/^\[[^]]+\]/ { id = substr($0, 2, index($0, "]") - 2) }
         /^enabled[[:space:]]*=[[:space:]]*(0|false|no)[[:space:]]*$/ { print id }' \
        /etc/dnf/repos.override.d/*.repo | sort -u | while read -r id; do
        [[ "$id" == *[*?]* ]] && continue
        disable_repo "$id"
    done
fi

# Turn off enabled repos whose local GPG key file does not exist (they cannot work anyway)
releasever=$(rpm -E %fedora)
basearch=$(uname -m)
awk -v rv="$releasever" -v ba="$basearch" '
    function keys(   n, i, a, k) {
        n = split($0, a, /[[:space:],]+/)
        for (i = 1; i <= n; i++) if (a[i] ~ /^file:\/\//) {
            k = substr(a[i], 8)
            gsub(/\$\{?releasever\}?/, rv, k)
            gsub(/\$\{?basearch\}?/, ba, k)
            print id, k
        }
    }
    /^\[[^]]+\]/ { id = substr($0, 2, index($0, "]") - 2); inkey = 0; next }
    /^gpgkey[[:space:]]*=/ { inkey = 1; sub(/^gpgkey[[:space:]]*=/, ""); keys(); next }
    inkey && /^[[:space:]]+[^[:space:]]/ { keys(); next }
    { inkey = 0 }
' /etc/yum.repos.d/*.repo | while read -r id key; do
    if [ ! -f "$key" ]; then
        echo "Repo ${id} needs missing key ${key}"
        disable_repo "$id"
    fi
done

### Initramfs
# Rebuilt last so it carries the boot animation (same dracut call Bazzite uses).
KVER=$(find /usr/lib/modules -mindepth 1 -maxdepth 1 -type d -printf '%f\n' | sort -V | tail -n 1)
export DRACUT_NO_XATTR=1
dracut --no-hostonly --kver "$KVER" --reproducible --zstd --add ostree --add fido2 \
    -f "/usr/lib/modules/$KVER/initramfs.img"
chmod 0600 "/usr/lib/modules/$KVER/initramfs.img"
lsinitrd "/usr/lib/modules/$KVER/initramfs.img" > /tmp/initramfs-files.txt
if ! grep -q 'plymouth/themes/houssamos/frame-1.png' /tmp/initramfs-files.txt; then
    echo "The HoussamOS boot animation is missing from the initramfs"
    exit 1
fi
